#!/bin/bash
# This script was auto-generated by prepare_lmer_analysis.py
# It runs a series of whole-brain LME analyses using AFNI's 3dLMEr.

# =============== CONFIGURATION ===============
RUN_LMER=1           # Run 3dLMEr for linear-mixed modeling
RUN_SMOOTH=1         # Calculate smoothness and extract subbricks fomr lmer_output
RUN_CLUST_SIM=1      # Run cluster simulations using 3dClustSim to find cluster extend thresholds
RUN_CLUST_THRES=1    # Find significant clusters using 3dClusterize
RUN_SUMMARY=1        # Extract results into summary txt file
# ==============================================

ROI='ventral_PFC'
STUDY_ALPHA=0.01

zstat_files=(cope1 cope3 cope5 cope7)
clinical_vars=("BDI_total" "CAPS_current")

#: <<'END'
for zstat in "${zstat_files[@]}"; do
    for var in "${clinical_vars[@]}"; do
        # Define the path to the data table
        DATA_TABLE=/Volumes/Morey/ProxPTSD.01/Analysis/derivatives/glmm_analysis/data_tables/gPPI/${ROI}/lmer_dataTable_${zstat}.txt
        
        # Base output folder for this zstat
        base_output=/Volumes/Morey/ProxPTSD.01/Analysis/derivatives/glmm_analysis/Results/gPPI_cope/${ROI}/${zstat}
        
        #================================
        # ------ Run LME Modeling ------
        #================================
        output="$base_output/${var}"
        mkdir -p "$output"
        
        if [ "$RUN_LMER" -eq 1 ]; then
        3dLMEr -prefix "$output/lmer_output.nii.gz" \
            -jobs 8 \
            -model "${var}+age+sex+(1|scanner)+(1|equipment)" \
            -qVars "age,${var}" \
            -mask "/Volumes/Morey/ProxPTSD.01/Analysis/derivatives/rois/mni/all_rois_mask.nii.gz" \
            -gltCode ${var} "${var}" \
            -dataTable @$DATA_TABLE
        fi
        
        # --- Dynamic Subbrick Extraction ---
        TARGET_CONTRAST="${var}"
        
        BETA_INDEX=$(3dinfo -label2index "${TARGET_CONTRAST}" "$output/lmer_output.nii.gz")
        STAT_INDEX=$(3dinfo -label2index "${TARGET_CONTRAST} Z" "$output/lmer_output.nii.gz")
        
        if [ "$STAT_INDEX" -lt 0 ]; then
            STAT_INDEX=$(3dinfo -label2index "${TARGET_CONTRAST} t" "$output/lmer_output.nii.gz")
        fi
        
        if [ "$STAT_INDEX" -lt 0 ] || [ "$BETA_INDEX" -lt 0 ]; then
            echo "❌ ERROR: Could not find subbricks for $TARGET_CONTRAST."
            continue 
        fi
        
        if [ "$RUN_SMOOTH" -eq 1 ]; then
            3dbucket -prefix "$output/beta.nii.gz" "$output/lmer_output.nii.gz[$BETA_INDEX]"
            3dbucket -prefix "$output/zstat.nii.gz" "$output/lmer_output.nii.gz[$STAT_INDEX]"
            3dcalc -a "$output/lmer_output.nii.gz[$STAT_INDEX]" -expr '-a' -prefix "$output/revzstat.nii.gz"
            
            3dFWHMx -mask "/Volumes/Morey/ProxPTSD.01/Analysis/derivatives/rois/mni/all_rois_mask.nii.gz" \
                    -input "$output/lmer_output.nii.gz[$STAT_INDEX]" \
                    -acf "$output/acf.1D" > "$output/acf_params.txt"
        fi

        if [ "$RUN_CLUST_SIM" -eq 1 ]; then
            ACF_PARAMS=$(sed -n '2p' "$output/acf_params.txt" | awk '{print $1, $2, $3}')
            3dClustSim -mask "/Volumes/Morey/ProxPTSD.01/Analysis/derivatives/rois/mni/all_rois_mask.nii.gz" \
                    -acf $ACF_PARAMS \
                    -athr $STUDY_ALPHA \
                    -prefix "$output/ClustSim"
        fi

        if [ "$RUN_CLUST_THRES" -eq 1 ]; then
            CLUST_THRESH=$(awk '$1 == 0.001000 {print $2}' "$output/ClustSim.NN2_bisided.1D")
            
            3dClusterize -inset "$output/lmer_output.nii.gz" \
                        -mask "/Volumes/Morey/ProxPTSD.01/Analysis/derivatives/rois/mni/all_rois_mask.nii.gz" \
                        -ithr $STAT_INDEX \
                        -idat $STAT_INDEX \
                        -NN 2 -bisided p=0.001 \
                        -clust_nvox $CLUST_THRESH \
                        -pref_map "$output/zstat_clustered.nii.gz" \
                        -pref_dat "$output/zstat_clustered_masked.nii.gz" \
                        -overwrite \
                        > "$output/cluster_report.txt"
        fi

    done
done
echo "All analyses and extractions complete!"

#END

if [ "$RUN_SUMMARY" -eq 1 ]; then
    # ==============================================================================
    # SUMMARY GENERATION (Robust Re-Calculation)
    # ==============================================================================
    echo "------------------------------------------------------"
    echo "Aggregating significant clusters (Recalculating all stats from clean Z-map)..."

    RESULTS_ROOT="/Volumes/Morey/ProxPTSD.01/Analysis/derivatives/glmm_analysis/Results/gPPI_cope/${ROI}"
    SUMMARY_FILE="${RESULTS_ROOT}/Global_Cluster_Report_${ROI}.txt"

    # Standard Header + P-value
    printf "Zstat\tModel_Var\tVolume\tCM_RL\tCM_AP\tCM_IS\tminRL\tmaxRL\tminAP\tmaxAP\tminIS\tmaxIS\tMean\tSEM\tMax_Int\tMI_RL\tMI_AP\tMI_IS\tPeak_P_bisided\n" > "$SUMMARY_FILE"


    if [ ${#zstat_files[@]} -eq 0 ]; then
        echo "ERROR: zstat_files array is empty."
        exit 1
    fi

    for zstat in "${zstat_files[@]}"; do
        for var in "${clinical_vars[@]}"; do
            
            model_dir="${RESULTS_ROOT}/${zstat}/${var}"
            report_path="${model_dir}/cluster_report.txt"
            
            # We need the cluster map (masks) and the zstat file
            cluster_map="${model_dir}/zstat_clustered.nii.gz"
            clean_zstat="${model_dir}/zstat.nii.gz" # This file is index 0
            
            if [ -f "$report_path" ] && [ -f "$clean_zstat" ]; then
                
                # Row counter to track Cluster ID (Line 1 = ID 1, Line 2 = ID 2)
                cluster_id=0
                
                grep -v '^#' "$report_path" | while read -r line; do
                    if [ -n "$line" ]; then
                        ((cluster_id++))
                        read -ra cols <<< "$line"
                        
                        # 1. Get Volume (Col 0) - This is trustworthy from the report
                        vol="${cols[0]}"
                        
                        # 2. RE-CALCULATE STATS directly from the clean Z-stat file
                        # 3dROIstats: Mean, Sigma (SD), Min, Max
                        # We rely on the Cluster Map ID matching the row number
                        stats=$(3dROIstats -mask "${cluster_map}<${cluster_id}>" -quiet -nzmean -sigma -minmax "$clean_zstat" 2>/dev/null)
                        
                        # Parse the stats
                        read -r true_mean true_sigma true_min true_max <<< "$stats"
                        
                        # 3. Calculate SEM (Sigma / sqrt(Volume))
                        true_sem=$(awk -v s="$true_sigma" -v v="$vol" 'BEGIN {print s / sqrt(v)}')
                        
                        # 4. Determine the True Peak (Max Intensity)
                        # If Mean is Negative, the Peak is the MINIMUM (e.g. -4.5).
                        # If Mean is Positive, the Peak is the MAXIMUM (e.g. +4.5).
                        true_peak=$(awk -v mn="$true_min" -v mx="$true_max" -v avg="$true_mean" 'BEGIN {print (avg < 0) ? mn : mx}')
                        
                        # 5. Overwrite the garbage columns in our array
                        cols[10]=$true_mean
                        cols[11]=$true_sem
                        cols[12]=$true_peak
                        
                        # 6. Calculate P-Value from the True Peak
                        # Use absolute value for 2-sided test
                        abs_peak=$(awk -v p="$true_peak" 'BEGIN {print (p < 0) ? -p : p}')
                        
                        p_val=$(dsetstat2p -inset "${clean_zstat}[0]" -statval "$abs_peak" -bisided -quiet)
                        
                        # 7. Write to summary file
                        printf "%s\t%s\t" "$zstat" "$var" >> "$SUMMARY_FILE"
                        for col in "${cols[@]}"; do printf "%s\t" "$col"; done >> "$SUMMARY_FILE"
                        printf "%s\n" "$p_val" >> "$SUMMARY_FILE"
                    fi
                done
                
                if grep -v '^#' "$report_path" | grep -q '[0-9]'; then
                    echo "Processed: $zstat | $var"
                fi
            else
                echo "Warning: Files missing for $zstat / $var"
            fi
            
        done
    done

    echo "Global summary saved to: $SUMMARY_FILE"
fi
echo "Script complete."
